set -eu; export LC_ALL=C CARGO_BUILD_JOBS=4; tmp=$(mktemp -d); trap 'rm -rf -- "$tmp"' EXIT; cargo build --locked --release -p catallax-cli --example predictor_corpus; python3 -c 'import json,sys; c=json.load(open("tools/predictor/corpus.json")); c["rows"]=[r for r in c["rows"] if r["id"]=="m8-k04-torus-pocket"]; assert len(c["rows"])==1; c["rows"][0]["max_work"]=2**62; json.dump(c,sys.stdout)' > "$tmp/corpus.json"; set -- target/release/examples/predictor_corpus run --root "$PWD" --corpus "$tmp/corpus.json" --out "$tmp/k04.jsonl" --rows m8-k04-torus-pocket --threads 1 --label cloud-uncapped; if command -v perf >/dev/null && perf stat -e instructions:u -- true >/dev/null 2>&1; then perf stat -x , -e instructions:u -- "$@"; else printf 'Hardware instruction counter unavailable on this runner\n' >&2; "$@"; fi; cat "$tmp/k04.jsonl" # Allow a 90-minute runner session; no case deadline.
